// Package instrument provides access to tradable instruments (BIST and
// US equities/ETFs, TEFAS funds, crypto pairs, gold) and search over them. This is shared market reference
// data, not user data, so it is not scoped by user_id.
package instrument

import (
	"context"
	"database/sql"
	_ "embed"
	"encoding/csv"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"slices"
	"strings"
	"time"
	"unicode"
	"unicode/utf8"

	"github.com/dogauzun/gelirgider/backend/internal/db"
)

// bistCSV is generated by cmd/symbols (go run ./cmd/symbols -market bist
// from backend/), which writes it straight into this package directory
// since go:embed needs it there. Refresh by hand by re-running that
// command.
//
//go:embed bist_symbols.csv
var bistCSV []byte

// usCSV is generated the same way with -market us.
//
//go:embed us_symbols.csv
var usCSV []byte

// tefasCSV is generated the same way with -market tefas.
//
//go:embed tefas_symbols.csv
var tefasCSV []byte

// cryptoTRYCSV and cryptoUSDCSV are generated the same way with -market
// crypto: BtcTurk TRY pairs as BTC-TRY and USDT pairs as BTC-USD (1 USDT
// treated as 1 USD).
//
//go:embed crypto_try_symbols.csv
var cryptoTRYCSV []byte

//go:embed crypto_usd_symbols.csv
var cryptoUSDCSV []byte

// goldCSV is hand-written, not generated: gold is priced in TRY. GRAM is
// the per-gram price; the coins (CEYREK, YARIM, TAM, ATA) have no fetched
// price and are valued with the user's manual prices, not gram
// price times fine weight, which would ignore the mint premium and spread.
//
//go:embed gold_symbols.csv
var goldCSV []byte

// seedSources are the CSV files Seed loads, each sharing one market and
// currency across all of its rows.
var seedSources = []struct {
	csv      []byte
	market   string
	currency string
}{
	{bistCSV, "BIST", "TRY"},
	{usCSV, "US", "USD"},
	{tefasCSV, "TEFAS", "TRY"},
	{cryptoTRYCSV, "CRYPTO", "TRY"},
	{cryptoUSDCSV, "CRYPTO", "USD"},
	{goldCSV, "GOLD", "TRY"},
}

// ErrNotFound is returned when no instrument matches the lookup.
var ErrNotFound = errors.New("instrument not found")

// Instrument is a tradable security.
type Instrument struct {
	ID       int64
	Symbol   string
	Market   string
	Name     string
	Currency string
}

// Repo provides access to instruments.
type Repo struct {
	db *sql.DB
}

// NewRepo returns a Repo backed by db.
func NewRepo(db *sql.DB) *Repo {
	return &Repo{db: db}
}

// turkishFoldPairs lists each Turkish diacritic with its closest ASCII
// letter, both cases, in strings.NewReplacer's old/new argument order.
var turkishFoldPairs = []string{
	"ç", "c", "Ç", "C",
	"ğ", "g", "Ğ", "G",
	"ı", "i", "İ", "I",
	"ö", "o", "Ö", "O",
	"ş", "s", "Ş", "S",
	"ü", "u", "Ü", "U",
}

// turkishFold folds a search query to ASCII. BIST names are seeded ASCII-only
// ("Turk Hava Yollari") but TEFAS names keep their diacritics ("YAPI KREDİ
// PORTFÖY ..."), so the stored name is folded as well (see foldedName) and
// the two meet in ASCII whichever way the user types. LIKE is only
// case-insensitive over ASCII, which folding İ/ı also takes care of.
var turkishFold = strings.NewReplacer(turkishFoldPairs...)

// foldedName applies the same folding to the stored name in SQL: one REPLACE
// per pair, nested. Generated from turkishFoldPairs so the two cannot drift.
// REPLACE is portable SQL, and the name match is a leading-wildcard LIKE no
// index could serve anyway, so folding costs no more than the scan already
// did.
var foldedName = func() string {
	expr := "name"
	for i := 0; i < len(turkishFoldPairs); i += 2 {
		expr = fmt.Sprintf("REPLACE(%s, '%s', '%s')", expr, turkishFoldPairs[i], turkishFoldPairs[i+1])
	}
	return expr
}()

// maxSearchRunes caps Search's query. SQLite rejects a LIKE pattern over
// 50,000 bytes with an error, so an unbounded q turned into a 500. No
// seeded symbol or name is near this long (the longest US name is ~250
// runes), so a longer q could not match anyway, and 1000 runes stays far
// below SQLite's limit even at 4 bytes a rune with every byte escaped.
const maxSearchRunes = 1000

// searchQuery is Search's statement, built once because foldedName is
// generated rather than literal. Its %s is the per-word match, one
// searchWordMatch (or goldWordMatch) per word of the query joined by AND;
// the derived table only names the folded expression, which
// SQLite still evaluates once per word.
var searchQuery = fmt.Sprintf(
	`SELECT id, symbol, market, name, currency FROM
	   (SELECT id, symbol, market, name, currency, %s AS folded FROM instruments) AS i
	 WHERE symbol LIKE ? ESCAPE '\' OR (%%s)
	 ORDER BY
	   CASE WHEN symbol = ? THEN 0
	        WHEN symbol LIKE ? ESCAPE '\' THEN 1
	        WHEN market = 'GOLD' AND ? = 1 THEN 2
	        WHEN symbol LIKE ? ESCAPE '\' AND market = 'BIST' THEN 3
	        WHEN symbol LIKE ? ESCAPE '\' THEN 4
	        WHEN folded LIKE ? ESCAPE '\' THEN 5
	        ELSE 6 END,
	   name,
	   symbol
	 LIMIT ?`, foldedName)

// searchWordMatch is one query word's condition: the word anywhere in the
// folded name, or the start of the symbol.
const searchWordMatch = `(folded LIKE ? ESCAPE '\' OR symbol LIKE ? ESCAPE '\')`

// goldWordMatch is searchWordMatch for a word that spells the GOLD market's
// own word: it also matches every GOLD instrument, whose names carry only
// the tr "Altın", so "gram gold" finds Gram Altın.
const goldWordMatch = `(` + searchWordMatch + ` OR market = 'GOLD')`

// maxSearchWords caps how many words Search matches one by one. Each word
// folds every name again (tens of ms over the seeded table), so a query of
// more words is matched whole, as a single word, the way every query was
// before the word search; a pasted full name still finds itself that way.
const maxSearchWords = 8

// goldMarketWords are the GOLD market's labels in search (market.GOLD:
// "Altın" in tr, "Gold" in en), folded and lower-cased as the query is.
var goldMarketWords = []string{"altin", "gold"}

// minGoldWordRunes is how much of a goldMarketWords entry a query word must
// spell before every GOLD instrument matches, so "a" or "g" alone does not
// put five coins ahead of the BIST symbols the user is typing.
const minGoldWordRunes = 3

// Search returns instruments matching q: a prefix match on symbol, or every
// whitespace-separated word of q found in the name or at the start of the
// symbol, in any order ("garanti para" finds GARANTİ PORTFÖY
// BİRİNCİ PARA ...), case-insensitive, up to limit rows. Results are
// ranked so an exact symbol match comes first, then crypto pairs whose base
// is the query ("btc" -> BTC-TRY, BTC-USD; only crypto symbols carry a
// hyphen), then every GOLD instrument when a word of the query is
// the start (at least minGoldWordRunes) of the market's own word, "altın"
// or "gold" (the coins' names are Turkish only and sort after
// gold funds, so the limit filled before them, and "gold" matched none;
// such a word matches every GOLD instrument, so "gram gold" finds
// Gram Altın), then BIST
// symbol-prefix matches (product is BIST-first), then other symbol-prefix
// matches, then names starting with the query, then names containing it.
// Name buckets
// are ordered by name, with no market tie-break: with ~1000 TEFAS funds
// and 31 BIST ETFs sharing the word PORTFOY, a BIST-first tie-break there
// filled the whole limit with one market and hid every other.
// Surrounding whitespace is ignored, so a blank q matches nothing.
// A q longer than maxSearchRunes also matches nothing, and so
// does one holding a control character: no instrument has one, and SQLite
// cuts a LIKE pattern at a NUL, so "%<NUL>%" would match everything.
func (r *Repo) Search(ctx context.Context, q string, limit int) ([]Instrument, error) {
	q = strings.TrimSpace(q)
	if q == "" || utf8.RuneCountInString(q) > maxSearchRunes || strings.ContainsFunc(q, unicode.IsControl) {
		return []Instrument{}, nil
	}
	words := strings.Fields(turkishFold.Replace(q))
	q = strings.Join(words, " ")
	if len(words) > maxSearchWords {
		words = []string{q}
	}
	gold := 0
	prefixPattern := likeEscape(q) + "%"
	matches := make([]string, len(words))
	args := []any{prefixPattern}
	for i, word := range words {
		matches[i] = searchWordMatch
		if isGoldWord(word) {
			matches[i] = goldWordMatch
			gold = 1
		}
		args = append(args, "%"+likeEscape(word)+"%", likeEscape(word)+"%")
	}
	args = append(args,
		strings.ToUpper(q), likeEscape(q)+"-%", gold, prefixPattern, prefixPattern, prefixPattern,
		limit,
	)
	return r.query(ctx, fmt.Sprintf(searchQuery, strings.Join(matches, " AND ")), args...)
}

// isGoldWord reports whether word, already folded, is the start (at least
// minGoldWordRunes) of one of goldMarketWords, case-insensitively.
func isGoldWord(word string) bool {
	lower := strings.ToLower(word)
	if len(lower) < minGoldWordRunes {
		return false
	}
	for _, w := range goldMarketWords {
		if strings.HasPrefix(w, lower) {
			return true
		}
	}
	return false
}

// query runs a SELECT of the instrument columns in order and scans every row.
func (r *Repo) query(ctx context.Context, query string, args ...any) ([]Instrument, error) {
	rows, err := r.db.QueryContext(ctx, query, args...)
	if err != nil {
		return nil, fmt.Errorf("query instruments: %w", err)
	}
	defer rows.Close()

	out := []Instrument{}
	for rows.Next() {
		var in Instrument
		if err := rows.Scan(&in.ID, &in.Symbol, &in.Market, &in.Name, &in.Currency); err != nil {
			return nil, fmt.Errorf("scan instrument: %w", err)
		}
		out = append(out, in)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate instruments: %w", err)
	}
	return out, nil
}

// Get returns the instrument with the given id, or ErrNotFound.
func (r *Repo) Get(ctx context.Context, id int64) (Instrument, error) {
	var in Instrument
	err := r.db.QueryRowContext(ctx,
		"SELECT id, symbol, market, name, currency FROM instruments WHERE id = ?", id,
	).Scan(&in.ID, &in.Symbol, &in.Market, &in.Name, &in.Currency)
	if errors.Is(err, sql.ErrNoRows) {
		return Instrument{}, ErrNotFound
	}
	if err != nil {
		return Instrument{}, fmt.Errorf("query instrument: %w", err)
	}
	return in, nil
}

// byIDsChunk caps the ids of one ByIDs query below modernc sqlite's limit of
// 32766 variables; a statement commit can name more ids.
const byIDsChunk = 10000

// ByIDs returns the instruments with the given ids, keyed by id, in one query
// per byIDsChunk ids. ErrNotFound when any requested id has no row, as Get
// would.
func (r *Repo) ByIDs(ctx context.Context, ids []int64) (map[int64]Instrument, error) {
	out := make(map[int64]Instrument, len(ids))
	for chunk := range slices.Chunk(ids, byIDsChunk) {
		placeholders, args := db.InList(chunk)
		rows, err := r.query(ctx,
			"SELECT id, symbol, market, name, currency FROM instruments WHERE id IN ("+placeholders+")",
			args...,
		)
		if err != nil {
			return nil, err
		}
		for _, in := range rows {
			out[in.ID] = in
		}
	}
	for _, id := range ids {
		if _, ok := out[id]; !ok {
			return nil, ErrNotFound
		}
	}
	return out, nil
}

// BySymbol returns the instrument traded as symbol on market, or ErrNotFound.
// The statement import matches a statement row to an existing instrument with
// it, and creates one only for a TEFAS fund code TEFAS confirms (ADR 0006).
func (r *Repo) BySymbol(ctx context.Context, market, symbol string) (Instrument, error) {
	var in Instrument
	err := r.db.QueryRowContext(ctx,
		"SELECT id, symbol, market, name, currency FROM instruments WHERE market = ? AND symbol = ?",
		market, symbol,
	).Scan(&in.ID, &in.Symbol, &in.Market, &in.Name, &in.Currency)
	if errors.Is(err, sql.ErrNoRows) {
		return Instrument{}, ErrNotFound
	}
	if err != nil {
		return Instrument{}, fmt.Errorf("query instrument by symbol: %w", err)
	}
	return in, nil
}

// All returns every instrument for market, ordered by symbol. Used by the
// price fetchers to map bulletin symbols to instrument ids without an IN
// clause per symbol (bulletins carry hundreds of symbols at once).
func (r *Repo) All(ctx context.Context, market string) ([]Instrument, error) {
	return r.query(ctx,
		"SELECT id, symbol, market, name, currency FROM instruments WHERE market = ? ORDER BY symbol",
		market,
	)
}

// Tracked returns instruments of market that appear in at least one
// transaction row (any user), ordered by symbol. Used by price fetchers
// that pay per symbol (e.g. internal/us) where fetching the whole market
// directory is not viable, so only symbols someone actually holds are
// fetched.
func (r *Repo) Tracked(ctx context.Context, market string) ([]Instrument, error) {
	return r.query(ctx,
		`SELECT id, symbol, market, name, currency FROM instruments
		 WHERE market = ? AND id IN (
		     SELECT DISTINCT instrument_id FROM transactions WHERE instrument_id IS NOT NULL
		 )
		 ORDER BY symbol`,
		market,
	)
}

// pauseAfter starts EachTracked's pause timer. It is time.After; tests swap
// it to cancel exactly at the pause, after the first instrument's rows are
// counted.
var pauseAfter = time.After

// EachTracked runs fn once for every instrument in tracked, in order, and
// returns the rows fn wrote and the number of instruments that failed. It
// is the loop every per-instrument price sync shares. Before
// fn's next call after one that made a request, it pauses for pause, so a
// failing source is still rate-limited; skipped means fn made no request
// (its range is already stored), so no pause is owed for it and none
// follows the last instrument. A failing instrument is logged at WARN and
// the rest continue; when every attempted one fails, err names them by
// noun ("funds"), so the run is stored as failed, not as a success with 0
// rows. A cancelled or expired ctx stops the loop with
// ctx's error and logs nothing, since nothing failed.
// ctx.Err() decides, not fn's error: net/http returns
// signal.NotifyContext's cancel cause, which does not wrap
// context.Canceled.
func EachTracked(ctx context.Context, tracked []Instrument, pause time.Duration, noun string, fn func(Instrument) (written int, skipped bool, err error)) (written, failed int, err error) {
	attempted := 0
	var lastErr error
	owed := false // the last call made a request and no pause followed it yet
	for _, in := range tracked {
		if owed {
			select {
			case <-ctx.Done():
				return written, failed, ctx.Err() // stopped during the pause
			case <-pauseAfter(pause):
			}
		}
		n, skipped, err := fn(in)
		written += n
		owed = !skipped
		if skipped {
			continue
		}
		attempted++
		if err != nil {
			if ctx.Err() != nil {
				return written, failed, ctx.Err() // stopped, not failed: no WARN
			}
			failed++
			lastErr = err
			slog.Default().Warn("instrument sync failed", "market", in.Market, "symbol", in.Symbol, "error", err)
		}
	}
	if failed > 0 && failed == attempted {
		return written, failed, fmt.Errorf("all %d %s failed, last: %w", failed, noun, lastErr)
	}
	return written, failed, nil
}

// Insert adds an instrument unless market+symbol already exists, and
// returns its id either way. Used by the BIST bulletin sync so a company
// listed after bist_symbols.csv was generated gets a row the day it first
// trades, instead of staying unknown until someone re-runs the importer by
// hand. The guard is the same portable INSERT ... SELECT ... WHERE NOT
// EXISTS that Seed uses, so a concurrent Seed cannot make this fail.
func (r *Repo) Insert(ctx context.Context, market, symbol, name, currency string) (int64, error) {
	_, err := r.db.ExecContext(ctx,
		`INSERT INTO instruments (symbol, market, name, currency)
		 SELECT ?, ?, ?, ?
		 WHERE NOT EXISTS (
		     SELECT 1 FROM instruments WHERE market = ? AND symbol = ?
		 )`,
		symbol, market, name, currency,
		market, symbol,
	)
	if err != nil {
		return 0, fmt.Errorf("insert instrument %s: %w", symbol, err)
	}
	in, err := r.BySymbol(ctx, market, symbol)
	if err != nil {
		return 0, err
	}
	return in.ID, nil
}

// Rename sets the instrument's display name. The TEFAS fetcher keeps a
// fund's name in step with TEFAS this way; the code stays.
func (r *Repo) Rename(ctx context.Context, id int64, name string) error {
	if _, err := r.db.ExecContext(ctx, "UPDATE instruments SET name = ? WHERE id = ?", name, id); err != nil {
		return fmt.Errorf("rename instrument %d: %w", id, err)
	}
	return nil
}

// likeEscape escapes LIKE wildcards in q so user input is matched literally.
func likeEscape(q string) string {
	r := strings.NewReplacer(`\`, `\\`, `%`, `\%`, `_`, `\_`)
	return r.Replace(q)
}

// Seed inserts instruments from the embedded CSVs (BIST, US, TEFAS, CRYPTO, GOLD) that
// do not already exist (matched on market+symbol), using a portable
// INSERT ... SELECT ... WHERE NOT EXISTS so it is safe to call on every
// startup.
func Seed(ctx context.Context, db *sql.DB) error {
	for _, src := range seedSources {
		if err := seedFile(ctx, db, src.csv, src.market, src.currency); err != nil {
			return fmt.Errorf("seed %s: %w", src.market, err)
		}
	}
	return nil
}

// seedFile inserts every row of one CSV under one market+currency. Rows
// are inserted inside a single transaction: at ~13,000 rows for the US
// file, one autocommit insert per row made startup noticeably slower (see
// PR description for before/after timing).
func seedFile(ctx context.Context, db *sql.DB, data []byte, market, currency string) error {
	reader := csv.NewReader(strings.NewReader(string(data)))
	header, err := reader.Read()
	if err != nil {
		return fmt.Errorf("read csv header: %w", err)
	}
	if len(header) != 2 || header[0] != "symbol" || header[1] != "name" {
		return fmt.Errorf("unexpected csv header: %v", header)
	}

	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("begin tx: %w", err)
	}
	defer tx.Rollback()

	for {
		record, err := reader.Read()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return fmt.Errorf("read csv row: %w", err)
		}
		symbol, name := record[0], record[1]
		_, err = tx.ExecContext(ctx,
			`INSERT INTO instruments (symbol, market, name, currency)
			 SELECT ?, ?, ?, ?
			 WHERE NOT EXISTS (
			     SELECT 1 FROM instruments WHERE market = ? AND symbol = ?
			 )`,
			symbol, market, name, currency,
			market, symbol,
		)
		if err != nil {
			return fmt.Errorf("insert instrument %s: %w", symbol, err)
		}
	}
	return tx.Commit()
}
